// ══════════════════════════════════════════════════════════════
//  ⚙️  แก้ 3 บรรทัดนี้ที่เดียว แล้วทั้งระบบใช้ได้เลย
// ══════════════════════════════════════════════════════════════
const SHEET_ID = 'PASTE_YOUR_GOOGLE_SHEET_ID';          // จาก URL ของ Google Sheet
const DISCORD_WEBHOOK = 'PASTE_YOUR_DISCORD_WEBHOOK_URL'; // Discord → Edit Channel → Integrations
let   SECRET = 'PASTE_YOUR_LINE_CHANNEL_SECRET';          // LINE Console → Basic settings

const ORDER_WEB_URL = '';   // เว็บสั่งอาหาร เช่น 'https://order.imjaicafe.com'
                            // ยังไม่มีเว็บ = เว้นว่างไว้ บอทจะบอกให้สั่งที่ร้าน/โทร/Grab แทน
// ══════════════════════════════════════════════════════════════

const crypto = require('crypto');
try { if ($env && $env.LINE_CHANNEL_SECRET) SECRET = $env.LINE_CHANNEL_SECRET; } catch (e) {}

const item = $input.first();
const h = item.json.headers || {};
let raw = '';
if (item.binary?.data?.data) raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
else raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body || {});

if (SECRET !== 'PASTE_YOUR_LINE_CHANNEL_SECRET') {
  const expect = crypto.createHmac('SHA256', SECRET).update(raw).digest('base64');
  const a = Buffer.from(expect), b = Buffer.from(String(h['x-line-signature'] || ''));
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('ลายเซ็นไม่ถูกต้อง — request นี้ไม่ได้มาจาก LINE');
  }
}

let body = {};
try { body = JSON.parse(raw || '{}'); } catch (e) {}

const now = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);
const out = [];
for (const ev of (body.events || [])) {
  if (ev.type !== 'message' || ev.message?.type !== 'text') continue;
  out.push({ json: {
    sheet_id: SHEET_ID,
    discord_webhook: DISCORD_WEBHOOK,
    order_web_url: ORDER_WEB_URL,
    line_user_id: ev.source?.userId || '',
    reply_token: ev.replyToken || '',
    message_text: ev.message.text || '',
    received_at: now,
  }});
}
return out;   // ถ้า LINE ยิงมา verify (ไม่มี event) จะได้ 0 item แล้วจบเลย

// รวมข้อมูลร้าน + ออเดอร์ของลูกค้า เป็นข้อความก้อนเดียวยัดให้ AI
const ev = $('⚙️ ตั้งค่าระบบ (แก้ที่นี่ที่เดียว)').first().json;
const rows = (node) => { try { return $(node).all().map((i) => i.json); } catch (e) { return []; } };

// 1) ข้อมูลร้าน
const store = rows('อ่านข้อมูลร้าน (StoreProfile)').filter((r) => r.key);
let ctx = '=== ข้อมูลร้าน ===\n' + store.map((r) => r.key + ': ' + r.value).join('\n');

// 2) คำถามที่พบบ่อย
const faq = rows('อ่าน FAQ (KnowledgeBase)').filter((r) => r.question);
ctx += '\n\n=== คำถามที่พบบ่อย ===\n'
     + faq.map((r) => '[' + r.category + '] ถาม: ' + r.question + '\nตอบ: ' + r.answer).join('\n');

// 3) เมนูและราคา — สถานะแปลงเป็นภาษาคนเพื่อกัน AI อ่านผิด
const avail = (v) => String(v).toUpperCase() === 'TRUE' ? 'พร้อมขาย' : '⛔ หมด/ไม่พร้อมขาย';
const menu = rows('อ่านเมนู (Products)').filter((r) => r.sku);
ctx += '\n\n=== เมนูและราคา ===\n' + menu.map((r) => [
  r.sku, r.name, 'หมวด: ' + r.category, 'ราคา ' + r.price + ' บาท',
  'ส่วนผสม: ' + (r.description || '-'),
  'สารก่อภูมิแพ้: ' + (r.allergens && r.allergens !== '-' ? r.allergens : 'ไม่มี'),
  avail(r.is_available),
  r.promotion ? 'โปร: ' + r.promotion : '',
].filter(Boolean).join(' | ')).join('\n');

// ออเดอร์ของลูกค้าคนนี้
let orders = [];
try { orders = $('อ่านออเดอร์ของลูกค้า').all().map((i) => i.json).filter((o) => o.order_id); } catch (e) {}
ctx += '\n\n=== ออเดอร์ของลูกค้าคนนี้ ===\n' + (orders.length
  ? orders.map((o) => [o.order_id, o.created_at, o.items, o.total + ' บาท',
      o.order_type === 'delivery' ? 'เดลิเวอรี' : 'รับที่ร้าน',
      'สถานะ: ' + o.status, o.eta ? 'ประมาณ ' + o.eta : '', o.note].filter(Boolean).join(' | ')).join('\n')
  : '(ลูกค้ายังไม่เคยสั่งอาหารผ่านแชทนี้)');

// คลังคำตอบที่ทีมงานยืนยันแล้ว — เอา 30 อันล่าสุดพอ กัน context บวม
let memo = [];
try {
  memo = $('อ่านคลังคำตอบที่ยืนยันแล้ว').all().map((i) => i.json).filter((m) => m.question && m.answer).slice(-30);
} catch (e) {}
if (memo.length) {
  ctx += '\n\n=== คำตอบมาตรฐานที่ทีมงานยืนยันแล้ว (ถ้าลูกค้าถามคล้ายข้อไหน ให้ตอบแนวเดียวกัน) ===\n'
       + memo.map((m) => 'ถาม: ' + m.question + '\nตอบ: ' + m.answer).join('\n');
}

ctx += '\n\n=== ช่องทางสั่งอาหาร ===\n' + (ev.order_web_url
  ? 'เว็บสั่งอาหาร: ' + ev.order_web_url +
    '\nเมื่อลูกค้าอยากสั่งอาหาร ให้ส่งลิงก์นี้พร้อมปิดท้ายข้อความด้วย [[QR]]' +
    ' ระบบจะแนบ QR code ให้ลูกค้าสแกนอัตโนมัติ'
  : 'ยังไม่มีเว็บสั่งอาหาร — ให้แนะนำลูกค้าสั่งที่ร้าน โทร 02-123-4567 หรือสั่งผ่าน Grab Food / LINE MAN');

ctx += '\n\n=== เวลาปัจจุบัน ===\n' + ev.received_at + ' น. (Asia/Bangkok)';

return [{ json: { ...ev, context_text: ctx, order_count: orders.length, memo_count: memo.length } }];

