// ตัดสินว่าต้องส่งเรื่องให้แอดมินทาง Discord ไหม
const ev = $('⚙️ ตั้งค่าระบบ (แก้ที่นี่ที่เดียว)').first().json;
let text = String($input.first().json.output || '').trim();

// สัญญาณจาก AI เอง
const flagged = text.includes('[[ADMIN]]');
text = text.replace(/\[\[ADMIN\]\]/g, '').trim();

// ตาข่ายกันพลาด เผื่อ AI ลืมใส่ [[ADMIN]]
const msg = ev.message_text.toLowerCase();
const HOT = ['คืนเงิน','ขอเงินคืน','ยกเลิกออเดอร์','ขอยกเลิก','ส่วนลด','ชดเชย','เคลม',
             'เส้นผม','แมลง','เศษแก้ว','อาหารเป็นพิษ','ท้องเสีย','แพ้','ฟ้อง','สคบ','ทนาย',
             'รีวิว 1 ดาว','ตัดเงินซ้ำ','แอดมิน','คุยกับคน','พนักงานตัวจริง','ด่วน','รีบ','รอนานมาก'];
const hit = HOT.find((k) => msg.includes(k));

const need_admin = flagged || !!hit;
const reason = flagged ? 'AI ขอให้แอดมินช่วย' : (hit ? 'พบคำที่ต้องให้คนดู: ' + hit : '');

// แนบ QR code เมื่อ AI สั่ง [[QR]] และมีการตั้งลิงก์เว็บไว้
const wantQr = text.includes('[[QR]]');
text = text.replace(/\[\[QR\]\]/g, '').trim();

if (!text) text = 'ขออภัยค่ะ ตอนนี้น้องอิ่มใจขัดข้องชั่วคราว รบกวนพิมพ์มาใหม่อีกครั้งนะคะ 🙏';

// ข้อความที่จะส่งกลับ LINE — อยากเพิ่มรูป/Flex/ปุ่มทีหลัง แก้ที่ตรงนี้จุดเดียว
const messages = [{ type: 'text', text }];
if (wantQr && ev.order_web_url) {
  const qr = 'https://quickchart.io/qr?size=500&margin=2&text=' + encodeURIComponent(ev.order_web_url);
  messages.push({ type: 'image', originalContentUrl: qr, previewImageUrl: qr });
}

return [{ json: { ...ev, reply_text: text, messages, need_admin, reason } }];

// ดึง Discord Webhook มาจาก node ⚙️ ตั้งค่าระบบ — ไม่ต้องพิมพ์ซ้ำ
const j = $('ตรวจคำตอบ').first().json;
const WEBHOOK = j.discord_webhook;
const name = $input.first().json.displayName || '(ไม่ทราบชื่อ)';

const payload = {
  username: 'อิ่มใจ Log',
  content: '@here 🔔 **มีลูกค้าต้องการให้แอดมินช่วย**',
  embeds: [{
    color: 15844367,
    fields: [
      { name: '👤 ชื่อลูกค้า', value: name, inline: true },
      { name: '🆔 LINE user id', value: '`' + j.line_user_id + '`', inline: true },
      { name: '🕒 เวลา', value: j.received_at, inline: true },
      { name: '💬 ลูกค้าพิมพ์ว่า', value: j.message_text.slice(0, 1000) },
      { name: '🤖 บอทตอบไปว่า', value: j.reply_text.slice(0, 1000) },
      { name: '📌 เหตุผลที่ส่งต่อ', value: j.reason || '-' },
    ],
    footer: { text: 'เปิด LINE OA Manager แล้วตอบลูกค้ารายนี้ต่อได้เลย' },
  }],
};
return [{ json: { webhook: WEBHOOK, payload } }];

// ⚠️ ใส่ Discord Webhook URL เดียวกับ node "สร้าง log แจ้งแอดมิน"
let WEBHOOK = 'https://discord.com/api/webhooks/PASTE_YOUR_DISCORD_WEBHOOK_URL';
try { if ($env && $env.IMJAI_DISCORD_WEBHOOK) WEBHOOK = $env.IMJAI_DISCORD_WEBHOOK; } catch (e) {}

const j = $input.first().json || {};
const ex = j.execution || {};
const stamp = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);

const payload = {
  username: 'อิ่มใจ System',
  content: '@here 🛑 **ระบบบอทมีปัญหา — ลูกค้าอาจไม่ได้รับคำตอบ รบกวนแอดมินเข้าดูแลใน LINE OA แทน**',
  embeds: [{
    color: 10038562,
    fields: [
      { name: '❌ พังที่ node', value: '`' + (ex.lastNodeExecuted || '-') + '`' },
      { name: '📄 error', value: '```' + String(ex.error?.message || '-').slice(0, 800) + '```' },
      { name: '🕒 เวลา', value: stamp, inline: true },
      { name: '🔢 execution', value: String(ex.id || '-'), inline: true },
    ],
  }],
};
return [{ json: { webhook: WEBHOOK, payload } }];
